insert into public.blog_posts (id,slug,title,excerpt,introduction,category,author,published_at,status,featured,pull_quote) values ('9c534426-a17e-46fc-a639-34617de24288','the-story-behind-100-pieces','The Story Behind 100 Pieces','Why limitation creates freedom — and why every Percent design disappears after the hundredth piece.','A clear ending gives every design meaning. One hundred pieces is enough to create a community without making the experience ordinary.','Brand','Percent Journal','2026-08-12T00:00:00+05:30','draft',true,'Once the hundredth piece is gone, that design becomes part of Percent history.') on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('a7f5d7bc-9a48-4d67-a3b9-af6aa7d06f32','9c534426-a17e-46fc-a639-34617de24288','Why 100?','["A fixed edition asks us to make clearer decisions. Every line, proportion and print has to earn its place before production begins.","The number is intentionally human: small enough to remain rare, yet large enough for one design to become part of many individual stories."]',0) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('41fb4dfe-f651-47bb-a2a3-55cbbec53398','9c534426-a17e-46fc-a639-34617de24288','Why Not Restock?','["Restocking would turn a promise into a marketing phrase. When the final piece leaves, the design is retired and the next idea gets room to exist."]',1) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('fdf1157c-0275-4698-a327-b6b7a074a2c2','9c534426-a17e-46fc-a639-34617de24288','Designing With an Ending','["Knowing a design has an ending changes how we make it and how it is worn. The piece becomes a timestamp rather than an endlessly repeated product."]',2) on conflict do nothing;
insert into public.blog_images (id,post_id,role,url,alt,width,height) values ('ad745608-8bfa-49bf-af82-44d9bf5e26e1','9c534426-a17e-46fc-a639-34617de24288','primary','https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1600&q=85','Limited Percent streetwear photographed in the city',1600,1100) on conflict do nothing;
