insert into public.blog_posts (id,slug,title,excerpt,introduction,category,author,published_at,status,featured,pull_quote) values ('9aa570c4-b18e-4287-ac62-91e01a7882f8','the-power-of-limited','The Power of Limited','Why fewer pieces create stronger connections.','Limited design is not about creating urgency. It is about creating focus, value and a stronger relationship with what we choose to own.','Brand','Percent Journal','2026-08-05T00:00:00+05:30','draft',false,'Limitation is not less possibility. It is more intention.') on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('b08a13e8-6ecc-410a-ad7b-8d619e99f190','9aa570c4-b18e-4287-ac62-91e01a7882f8','Fewer, Better Choices','["When options become endless, character can disappear. A smaller edition gives one idea the space to be understood and remembered."]',0) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('601c0b09-fb57-4e8e-a622-75cd5df80aae','9aa570c4-b18e-4287-ac62-91e01a7882f8','A Shared Connection','["Every owner is part of a group that can never grow beyond the edition. The connection is quiet, but it is real."]',1) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('a1d8b6d9-0edf-4aeb-a4dd-6a12ca18330e','9aa570c4-b18e-4287-ac62-91e01a7882f8','Rarity With Purpose','["For Percent, rarity is a result of restraint. We stop because the boundary is part of the design."]',2) on conflict do nothing;
insert into public.blog_images (id,post_id,role,url,alt,width,height) values ('52c716a6-d799-4cf9-af88-df5b90d32d5a','9aa570c4-b18e-4287-ac62-91e01a7882f8','primary','https://images.unsplash.com/photo-1523398002811-999ca8dec234?auto=format&fit=crop&w=1200&q=85','A considered streetwear collection in neutral tones',1200,900) on conflict do nothing;
insert into public.blog_posts (id,slug,title,excerpt,introduction,category,author,published_at,status,featured,pull_quote) values ('e42fd3ed-02ca-4c66-a21e-62c8cbda448f','intentional-design','Intentional Design','A look into how Percent pieces move from idea to finished form.','Every Percent piece begins with a reason. The process removes what is unnecessary until the idea feels direct, wearable and distinct.','Design','Percent Journal','2026-07-28T00:00:00+05:30','draft',false,'The strongest detail is often the one that knows when to stop.') on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('17535b97-416e-4184-a316-3c396dc65af7','e42fd3ed-02ca-4c66-a21e-62c8cbda448f','Start With Meaning','["We begin with a thought rather than a trend. References are collected, challenged and reduced into one clear visual direction."]',0) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('e9a62fa3-1df1-48a3-a5c5-18aca775861f','e42fd3ed-02ca-4c66-a21e-62c8cbda448f','Refine the Form','["Placement, scale and negative space are tested on the garment itself. The design has to work while moving, not only on a screen."]',1) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('8413b8e2-c093-43e8-a1b0-cfb84846db2e','e42fd3ed-02ca-4c66-a21e-62c8cbda448f','Finish With Restraint','["A piece is ready when nothing feels accidental. Production begins only after the material and artwork support the same intention."]',2) on conflict do nothing;
