insert into public.blog_posts (id,slug,title,excerpt,introduction,category,author,published_at,status,featured,pull_quote) values ('96283191-1375-4325-ac5e-ed5ad403feb4','style-in-real-life','Style in Real Life','How people make Percent their own.','A garment is unfinished until someone wears it. Personal styling gives every limited piece a second creative life beyond the studio.','Community','Percent Journal','2026-07-19T00:00:00+05:30','draft',false,'Identity begins where styling rules end.') on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('82d1a470-79aa-49d5-a6c3-4de7d72edd27','96283191-1375-4325-ac5e-ed5ad403feb4','One Piece, Different Stories','["The same shirt can feel quiet, graphic, polished or relaxed depending on the person wearing it. That variation is the point."]',0) on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('de580597-6c29-4e6f-aab4-91a45b2e4e24','96283191-1375-4325-ac5e-ed5ad403feb4','Beyond the Lookbook','["Campaign images introduce a direction. The community takes it further by mixing Percent with the clothes and objects that already matter to them."]',1) on conflict do nothing;
