insert into public.blog_posts (id,slug,title,excerpt,introduction,category,author,published_at,status,featured,pull_quote) values ('49f58a38-2da6-4f63-a1d1-b8290be0f1a1','inside-the-studio','Inside the Studio','Ideas, experiments and everything between concept and production.','The studio is where unfinished thoughts become physical decisions through testing, comparison and constant editing.','Process','Percent Journal','2026-07-10T00:00:00+05:30','draft',false,'The studio is less about inspiration than it is about better decisions.') on conflict do nothing;
insert into public.blog_sections (id,post_id,heading,paragraphs,sort_order) values ('0131ebbc-4421-4b8c-a5b0-715d018c2c63','49f58a38-2da6-4f63-a1d1-b8290be0f1a1','Collect and Question','["References come from typography, architecture, conversations and ordinary details. We keep only what supports the central idea."]',0) on conflict do nothing;
